local fbStatus = FG:AddLabel("", true)
FG:AddButton({
    Text = "📨 ส่ง",
    Func = function()
        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            safeSet(fbStatus, string.format("กรุณารอ %d วินาทีก่อนส่งอีกครั้ง", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback))))
            return
        end
        local ftype = tostring((Options.FeedbackType and Options.FeedbackType.Value) or "Suggestion"):lower()
        local msg   = M.trim((Options.FeedbackMsg and Options.FeedbackMsg.Value) or "")
        if msg == "" then safeSet(fbStatus, "ข้อความว่างเปล่า"); return end
        if #msg > 500 then safeSet(fbStatus, "ข้อความยาวเกินไป (สูงสุด 500 ตัวอักษร)"); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            safeSet(fbStatus, "ไม่อนุญาตให้ใส่ลิงก์"); return
        end
        safeSet(fbStatus, "กำลังส่ง...")
        task.spawn(function()
            local sok, err = M.sendFeedback(ftype, msg, (preCheck and preCheck.session_token) or "")
            if sok then
                lastFeedback = tick()
                safeSet(fbStatus, "✅ ส่งแล้ว ขอบคุณ!")
                pcall(function() Options.FeedbackMsg:SetValue("") end)
                Library:Notify({Title = "COMBOWICK", Description = "ส่งความคิดเห็นของคุณแล้ว ขอบคุณ!", Time = 3})
            else
                safeSet(fbStatus, ERRMAP[err] or ("ส่งไม่สำเร็จ: " .. tostring(err)))
            end
        end)
    end,
})
